create table if not exists public.driver_applications(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,license_number text not null,experience_years smallint not null default 0 check(experience_years between 0 and 60),requested_vehicle_type text not null check(requested_vehicle_type in ('car','bike','cng')),note text,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewer_id uuid references public.profiles(id),reviewed_at timestamptz,rejection_reason text,created_at timestamptz not null default now());
alter table public.driver_applications enable row level security;
drop policy if exists driver_applications_read_owner_admin on public.driver_applications;create policy driver_applications_read_owner_admin on public.driver_applications for select to authenticated using(user_id=(select auth.uid()) or (select private.drive_role())='admin'::public.drive_role);
drop policy if exists driver_applications_insert_passenger on public.driver_applications;create policy driver_applications_insert_passenger on public.driver_applications for insert to authenticated with check(user_id=(select auth.uid()) and (select private.drive_role())='passenger'::public.drive_role);
drop policy if exists driver_applications_admin_update on public.driver_applications;create policy driver_applications_admin_update on public.driver_applications for update to authenticated using((select private.drive_role())='admin'::public.drive_role) with check((select private.drive_role())='admin'::public.drive_role);
grant select,insert,update on public.driver_applications to authenticated;
